CREATE TYPE "PanelReviewState" AS ENUM ('not_started','in_review','submitted','changes_requested');
CREATE TYPE "ReviewerRecommendation" AS ENUM ('shortlist','hold','needs_information','do_not_advance');
CREATE TABLE "review_assignments" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"candidate_evaluation_id" TEXT NOT NULL REFERENCES "candidate_evaluations"("id") ON DELETE CASCADE,"reviewer_member_id" TEXT NOT NULL REFERENCES "organization_members"("id") ON DELETE CASCADE,"state" "PanelReviewState" NOT NULL DEFAULT 'not_started',"assigned_by_id" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("organization_id","candidate_evaluation_id","reviewer_member_id"));
CREATE TABLE "panel_reviews" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"assignment_id" TEXT NOT NULL REFERENCES "review_assignments"("id"),"candidate_evaluation_id" TEXT NOT NULL REFERENCES "candidate_evaluations"("id"),"reviewer_member_id" TEXT NOT NULL REFERENCES "organization_members"("id"),"recommendation" "ReviewerRecommendation" NOT NULL,"summary" TEXT NOT NULL,"criterion_feedback" JSONB NOT NULL,"submitted_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "review_comments" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"candidate_evaluation_id" TEXT NOT NULL REFERENCES "candidate_evaluations"("id"),"criterion_id" TEXT,"evidence_claim_id" TEXT,"author_member_id" TEXT NOT NULL REFERENCES "organization_members"("id"),"body" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "shortlist_decisions" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"candidate_evaluation_id" TEXT NOT NULL REFERENCES "candidate_evaluations"("id"),"candidate_id" TEXT NOT NULL REFERENCES "candidates"("id"),"position_id" TEXT NOT NULL,"decision" TEXT NOT NULL CHECK("decision" IN ('shortlisted','hold','not_advancing')),"rationale" TEXT NOT NULL,"decided_by_id" TEXT NOT NULL,"decided_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "decision_events" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"shortlist_decision_id" TEXT NOT NULL REFERENCES "shortlist_decisions"("id"),"event_type" TEXT NOT NULL,"actor_user_id" TEXT NOT NULL,"metadata" JSONB NOT NULL DEFAULT '{}',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "notifications" ("id" TEXT PRIMARY KEY,"organization_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"recipient_member_id" TEXT NOT NULL REFERENCES "organization_members"("id") ON DELETE CASCADE,"kind" TEXT NOT NULL,"subject_type" TEXT NOT NULL,"subject_id" TEXT NOT NULL,"body" TEXT NOT NULL,"read_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "review_assignments_organization_id_reviewer_member_id_state_idx" ON "review_assignments"("organization_id","reviewer_member_id","state");
CREATE INDEX "panel_reviews_organization_id_candidate_evaluation_id_submitted_at_idx" ON "panel_reviews"("organization_id","candidate_evaluation_id","submitted_at");
CREATE INDEX "review_comments_organization_id_candidate_evaluation_id_created_at_idx" ON "review_comments"("organization_id","candidate_evaluation_id","created_at");
CREATE INDEX "shortlist_decisions_organization_id_candidate_evaluation_id_decided_at_idx" ON "shortlist_decisions"("organization_id","candidate_evaluation_id","decided_at");
CREATE INDEX "decision_events_organization_id_shortlist_decision_id_created_at_idx" ON "decision_events"("organization_id","shortlist_decision_id","created_at");
CREATE INDEX "notifications_organization_id_recipient_member_id_created_at_idx" ON "notifications"("organization_id","recipient_member_id","created_at");
